\set ON_ERROR_STOP on
-- Only a disposable PostgreSQL database in existing GitHub CI.
do $$ begin
 if current_database()<>'saturn_rollback_probe' then raise exception 'Requires disposable rollback test database'; end if;
 if to_regclass('public.clubs') is not null then raise exception 'Requires empty database'; end if;
end $$;
create schema auth;
create schema private;
create schema fixture;
create table auth.users(id uuid,is_anonymous boolean not null);
create table private.ppm_guest_auth_gate_v1(id boolean primary key,enabled boolean,verified_at timestamptz);
insert into private.ppm_guest_auth_gate_v1 values(true,false,null);
do $$ begin
 if not exists(select 1 from pg_roles where rolname='anon') then create role anon nologin; end if;
 if not exists(select 1 from pg_roles where rolname='authenticated') then create role authenticated nologin; end if;
 if not exists(select 1 from pg_roles where rolname='service_role') then create role service_role nologin; end if;
end $$;
create function fixture.assert_ok(ok boolean,description text) returns void language plpgsql as $$begin
 if ok is distinct from true then raise exception 'FAIL: %',description; end if;
 raise notice 'PASS: %',description;
end$$;
