create policy fixture_existing on public.clubs for select to authenticated using(true);
create function fixture.old_trigger() returns trigger language plpgsql as $$begin return new;end$$;
create trigger fixture_existing before insert on public.clubs for each row execute function fixture.old_trigger();

-- Execute the exact operator capture script. All definitions are synthetic.
\ir ../saturn_capture_predeploy_rollback.sql
select fixture.assert_ok((select payload_md5=md5(payload::text) and jsonb_array_length(payload->'functions')=83 and jsonb_array_length(payload->'relations')=24 from private.saturn_predeploy_schema_backup_v1),'rollback capture inventory and checksum verified');
select fixture.assert_ok(not has_table_privilege('anon','private.saturn_predeploy_schema_backup_v1','SELECT') and not has_table_privilege('authenticated','private.saturn_predeploy_schema_backup_v1','SELECT') and not has_table_privilege('service_role','private.saturn_predeploy_schema_backup_v1','SELECT'),'rollback metadata inaccessible to browser and service role');

-- Simulate scoped release changes before any guest is created.
create or replace function public.equipment_purchase_item() returns integer language sql as $$select 2$$;
create or replace function public.finance_credit_to_club() returns integer language sql as $$select 3$$;
revoke all on function public.finance_credit_to_club() from PUBLIC,anon,authenticated;
grant execute on function public.finance_credit_to_club() to service_role;
create policy saturn_trial_clubs_update_v1 on public.clubs as restrictive for update to authenticated using(false);
create trigger saturn_guard_developing_club_v1 before insert on public.clubs for each row execute function fixture.old_trigger();
alter view public.club_roster set(security_invoker=true);
create table public.saturn_test_accounts_v1(user_id uuid);
create table private.saturn_test_club_rollout_v1(enabled boolean,public_signup boolean);
insert into private.saturn_test_club_rollout_v1 values(false,false);
create function public.saturn_create_test_club_v1() returns integer language sql as $$select 1$$;
grant execute on function public.saturn_create_test_club_v1() to authenticated;

\ir ../saturn_pre_guest_targeted_rollback.sql
select fixture.assert_ok(public.equipment_purchase_item()=1 and public.finance_credit_to_club()=1,'targeted rollback restores captured routine definitions');
select fixture.assert_ok(not has_function_privilege('authenticated','public.finance_credit_to_club()','EXECUTE') and has_function_privilege('service_role','public.finance_credit_to_club()','EXECUTE'),'targeted rollback keeps finance hardening in place');
select fixture.assert_ok(not exists(select 1 from pg_policies where policyname='saturn_trial_clubs_update_v1') and exists(select 1 from pg_policies where policyname='fixture_existing'),'targeted rollback removes only new Saturn policy');
select fixture.assert_ok(not exists(select 1 from pg_trigger where tgname='saturn_guard_developing_club_v1') and exists(select 1 from pg_trigger where tgname='fixture_existing'),'targeted rollback removes only new Saturn trigger');
select fixture.assert_ok(not exists(select 1 from pg_class where oid='public.club_roster'::regclass and coalesce(reloptions,array[]::text[]) @> array['security_invoker=true']),'targeted rollback restores baseline view option');
select fixture.assert_ok(not has_function_privilege('authenticated','public.saturn_create_test_club_v1()','EXECUTE') and to_regclass('public.saturn_test_accounts_v1') is not null,'targeted rollback revokes creation without dropping lifecycle tables');
\echo 'SATURN TARGETED ROLLBACK FIXTURE PASSED (synthetic schema; no production recovery executed)'
